// FUNCTION: BFME2 0x00493845 size=358 name=?createViewObject@SpecialPowerModule@@IAEXPBUCoord3D@@@Z evidence=N:ledger
void SpecialPowerModule::createViewObject(const Coord3D *location)
{
	if (location == NULL)
		return;

	const SpecialPowerTemplate *powerTemplate = getSpecialPowerModuleData()->m_specialPowerTemplate;
	if (powerTemplate == NULL)
		return;

	Real visionRange = powerTemplate->getFO()->m_viewObjectRange;
	UnsignedInt visionDuration = powerTemplate->getFO()->m_viewObjectDuration;
	if (visionRange == 0 || visionDuration == 0)
		return;

	AsciiString objectName = TheWritableGlobalData->m_specialPowerViewObject;
	if (objectName.isEmpty())
		return;

	const ThingTemplate *viewObjectTemplate = TheThingFactory->findTemplate(objectName);
	if (viewObjectTemplate == NULL)
		return;

	CreateMask mask;
	memset(&mask, 0, sizeof(mask));

	Object *viewObject = TheThingFactory->newObject(viewObjectTemplate,
		getObject()->getControllingPlayer()->getDefaultTeam(), &mask, (ObjectID)0);
	if (viewObject == NULL)
		return;

	viewObject->setPosition(location);
	viewObject->setShroudClearingRange(visionRange);
	viewObject->updateShroudNow();

	static NameKeyType key_DeletionUpdate = TheNameKeyGenerator->nameToKey("DeletionUpdate");
	DeletionUpdate *deletion = (DeletionUpdate *)viewObject->findUpdateModule(key_DeletionUpdate);
	if (deletion)
		deletion->setLifetimeRange(visionDuration, visionDuration);
}

